# PTX source for fp16 matrix multiplication (tile size 16x16) on SM80
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry kernel_matmul(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 N
)
{
    // ------------------------------
    // Registers
    // ------------------------------
    .reg .b64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u32 %N;

    .reg .u32 %ctaid_x, %ctaid_y;
    .reg .u32 %tid_x, %tid_y;

    .reg .u32 %row, %col;
    .reg .u32 %k_tile;
    .reg .u32 %i;

    .reg .f32 %acc;
    .reg .f16 %a_val, %b_val, %c_val;
    .reg .f32 %a_f32, %b_f32;

    .reg .u32 %idx;
    .reg .b64 %addr;
    .reg .b64 %as_base, %bs_base, %as_addr, %bs_addr;

    .reg .pred %p0, %p1, %p2, %p3, %p4;

    // ------------------------------
    // Load kernel parameters
    // ------------------------------
    ld.param.u64 %a_ptr, [A];
    ld.param.u64 %b_ptr, [B];
    ld.param.u64 %c_ptr, [C];
    ld.param.u32 %N,    [N];

    // ------------------------------
    // Built‑in IDs
    // ------------------------------
    mov.u32 %ctaid_x, %ctaid.x;
    mov.u32 %ctaid_y, %ctaid.y;
    mov.u32 %tid_x,   %tid.x;
    mov.u32 %tid_y,   %tid.y;

    // ------------------------------
    // Constants
    // ------------------------------
    .equ TILE, 16;

    // ------------------------------
    // Compute global row / col of the element this thread will write
    // ------------------------------
    mul.lo.u32 %row, %ctaid_y, TILE;
    add.u32    %row, %row, %tid_y;

    mul.lo.u32 %col, %ctaid_x, TILE;
    add.u32    %col, %col, %tid_x;

    // ------------------------------
    // Accumulator init
    // ------------------------------
    mov.f32 %acc, 0f00000000;          // 0.0f

    // ------------------------------
    // Shared memory tiles (fp16)
    // ------------------------------
    .shared .align 2 .b16 As[TILE * TILE];
    .shared .align 2 .b16 Bs[TILE * TILE];

    // Store base addresses of shared arrays
    mov.u64 %as_base, As;
    mov.u64 %bs_base, Bs;

    // ------------------------------
    // Loop over K dimension tiles
    // ------------------------------
    mov.u32 %k_tile, 0;

LOOP_TILES:
    // if k_tile >= N -> exit
    setp.ge.u32 %p0, %k_tile, %N;
    @%p0 bra END_LOOP;

    // -------------------------------------------------
    // Load A tile element into shared memory
    // -------------------------------------------------
    // global index: row * N + (k_tile + tid_x)
    mul.wide.u32 %addr, %row, %N;                 // row * N
    add.u32       %idx, %k_tile, %tid_x;          // column offset
    add.u32       %addr, %addr, %idx;             // linear index
    mul.wide.u32 %addr, %addr, 2;                 // fp16 -> 2 bytes
    add.u64       %addr, %a_ptr, %addr;
    ld.global.f16 %a_val, [%addr];

    // shared offset = tid_y * TILE + tid_x
    mul.lo.u32 %idx, %tid_y, TILE;
    add.u32    %idx, %idx, %tid_x;
    mul.wide.u32 %as_addr, %idx, 2;
    add.u64 %as_addr, %as_addr, %as_base;
    st.shared.f16 [%as_addr], %a_val;

    // -------------------------------------------------
    // Load B tile element into shared memory
    // -------------------------------------------------
    // global index: (k_tile + tid_y) * N + col
    add.u32 %idx, %k_tile, %tid_y;               // row index inside B
    mul.wide.u32 %addr, %idx, %N;                // (row) * N
    add.u32 %addr, %addr, %col;                  // + col
    mul.wide.u32 %addr, %addr, 2;                // fp16 bytes
    add.u64 %addr, %b_ptr, %addr;
    ld.global.f16 %b_val, [%addr];

    // shared offset = tid_y * TILE + tid_x (same idx as above)
    mul.wide.u32 %bs_addr, %idx, 2;   // reuse %idx (tid_y*TILE+tid_x)
    add.u64 %bs_addr, %bs_addr, %bs_base;
    // but we need (tid_y * TILE + tid_x) for B as well; compute:
    mul.lo.u32 %idx, %tid_y, TILE;
    add.u32    %idx, %idx, %tid_x;
    mul.wide.u32 %bs_addr, %idx, 2;
    add.u64 %bs_addr, %bs_addr, %bs_base;
    st.shared.f16 [%bs_addr], %b_val;

    // -------------------------------------------------
    // Synchronise threads before computing
    // -------------------------------------------------
    bar.sync 0;

    // -------------------------------------------------
    // Compute partial dot product for this tile
    // -------------------------------------------------
    mov.u32 %i, 0;
LOOP_K:
    setp.ge.u32 %p1, %i, TILE;
    @%p1 bra END_K;

    // a = As[tid_y * TILE + i]
    mul.lo.u32 %idx, %tid_y, TILE;
    add.u32    %idx, %idx, %i;
    mul.wide.u32 %as_addr, %idx, 2;
    add.u64 %as_addr, %as_addr, %as_base;
    ld.shared.f16 %a_val, [%as_addr];

    // b = Bs[i * TILE + tid_x]
    mul.lo.u32 %idx, %i, TILE;
    add.u32    %idx, %idx, %tid_x;
    mul.wide.u32 %bs_addr, %idx, 2;
    add.u64 %bs_addr, %bs_addr, %bs_base;
    ld.shared.f16 %b_val, [%bs_addr];

    // Convert to fp32
    cvt.f32.f16 %a_f32, %a_val;
    cvt.f32.f16 %b_f32, %b_val;

    // FMA
    fma.rn.f32 %acc, %a_f32, %b_f32, %acc;

    // i++
    add.u32 %i, %i, 1;
    bra LOOP_K;
END_K:

    // Synchronise before loading next tile
    bar.sync 0;

    // k_tile += TILE
    add.u32 %k_tile, %k_tile, TILE;
    bra LOOP_TILES;

END_LOOP:
    // -------------------------------------------------
    // Write result if within matrix bounds
    // -------------------------------------------------
    setp.lt.u32 %p2, %row, %N;
    setp.lt.u32 %p3, %col, %N;
    and.pred %p4, %p2, %p3;
    @!%p4 bra END_WRITE;

    // Convert accumulator to fp16 (round‑to‑nearest)
    cvt.rn.f16.f32 %c_val, %acc;

    // global address for C[row, col]
    mul.wide.u32 %addr, %row, %N;
    add.u32 %addr, %addr, %col;
    mul.wide.u32 %addr, %addr, 2;
    add.u64 %addr, %c_ptr, %addr;

    st.global.f16 [%addr], %c_val;

END_WRITE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load PTX module (provided by the harness)
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A, B):
        """
        A, B : torch.cuda.FloatTensor (fp16) with shape (N, N)
        returns C = A @ B (fp16)
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        N = A.size(0)
        C = torch.empty_like(A)

        # Grid/Block dimensions (tile size 16)
        block = (16, 16, 1)
        grid = ((N + 15) // 16, (N + 15) // 16, 1)

        # Argument list: raw device pointers + matrix dimension
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            N
        ]

        # Launch kernel via harness
        ptx_launch(self.module, "kernel_matmul", grid, block, args)

        return C
